def reverse(nums, left, right):
    while left < right:
        nums[left], nums[right] = nums[right], nums[left]
        left += 1
        right -= 1

class Solution {
    public void rotate(int[] nums, int k) {
        k %= nums.length;
        reverse(nums, 0, nums.length - 1);   // 1. reverse everything
        reverse(nums, 0, k - 1);             // 2. fix the first k
        reverse(nums, k, nums.length - 1);   // 3. fix the rest
    }

    private void reverse(int[] nums, int left, int right) {
        while (left < right) {
            int temp = nums[left];
            nums[left] = nums[right];
            nums[right] = temp;
            left++;
            right--;
        }
    }
}

class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        int n = nums.size();
        k %= n;
        reverse(nums.begin(), nums.end());          // 1. reverse everything
        reverse(nums.begin(), nums.begin() + k);    // 2. fix the first k
        reverse(nums.begin() + k, nums.end());      // 3. fix the rest
    }
};
